const patch = "*** Begin Patch
*** Update File: /app/output/gen.py
@@
 def joints(row, dt=0.1, note=""):
     return r.submit("joint_position", np.asarray(row, dtype=np.float32), dt=dt, note=note)
+
+def drive(x=0.0, y=0.0, yaw=0.0, seconds=0.2, note=""):
+    """Hold one safe base increment while retaining the observed trunk/arm/gripper joints."""
+    p = np.asarray(obs.meta["proprio"]["now"], dtype=np.float32)
+    row = np.concatenate(([x, y, yaw], p[:22]))
+    return joints(row[None, :], dt=seconds, note=note or "short base increment")
*** End Patch";
text(await tools.apply_patch(patch));

