import json,numpy as np
for f in ['front_sink2','view_sink_again','plate_sidepose','plate_right_above']:
 p='/app/output/'+f+'_meta.json'
 try:m=json.load(open(p))
 except:continue
 c=m['cameras']['robot_r1:zed_link:Camera:0'];T=np.array(c['extrinsic_cv']);K=np.array(c['intrinsic_cv']);o=-T[:,:3].T@T[:,3]
 print('\n',f,'origin',o.round(3),'base',np.array(m['proprio']['now'][28:35]).round(3))
 for uv in [(62,178),(171,160),(182,150),(70,170),(100,140)]:
  d=T[:,:3].T@np.linalg.inv(K)@np.array([*uv,1.]);
  z=.9;s=(z-o[2])/d[2]
  if s>0:print(uv,(o+s*d).round(3))
